CREATE TRIGGER dbo.[TR_P7_12345678123412341234123456789abc_Audit] ON dbo.[AuditCatalogChanges] AFTER INSERT AS
BEGIN
    SET NOCOUNT ON;
    IF NOT EXISTS(SELECT 1 WHERE DB_NAME()=N'NuanSystem_Phase7_12345678123412341234123456789abc_B' AND DB_ID()>4 AND TRY_CONVERT(uniqueidentifier,(SELECT TRY_CONVERT(nvarchar(128),value) FROM sys.extended_properties WHERE class=0 AND name=N'Phase7.RunId'))='12345678-1234-1234-1234-123456789abc' AND (SELECT TRY_CONVERT(nvarchar(128),value) FROM sys.extended_properties WHERE class=0 AND name=N'Phase7.Purpose')=N'BackendTransactionValidation'
        AND TRY_CONVERT(uniqueidentifier,TRY_CONVERT(nvarchar(128),SESSION_CONTEXT(N'P7_RunId')))='12345678-1234-1234-1234-123456789abc'
        AND TRY_CONVERT(int,TRY_CONVERT(nvarchar(32),SESSION_CONTEXT(N'P7_CompanyId')))=902
        AND TRY_CONVERT(nvarchar(40),SESSION_CONTEXT(N'P7_FaultPoint'))=N'AuditInsert') RETURN;
    IF EXISTS(SELECT 1 FROM inserted i INNER JOIN dbo.BusinessPartners b ON i.RecordId=CONVERT(nvarchar(80),b.Id) WHERE i.EntityName=N'BusinessPartners' AND LEFT(b.Code,12)=N'P7_12345678_' AND b.Code=TRY_CONVERT(nvarchar(50),SESSION_CONTEXT(N'P7_CaseCode')))
        THROW 51505, N'PHASE7_SQL_AUDITINSERT', 1;
END;

